	/**
	 * この画面のステータスを設定します。
	 *
	 * @param status ステータス
	 */
	public void setStatus(String status) {
		super.setStatus(status);
		if (INS.equals(status)) {
			setINSStatus();
		}
		else if (BNDL.equals(status)) {
			setBNDLStatus();
		}
		else if (FIX_I.equals(status)) {
			setFIX_IStatus();
		}
		else if (SRCH_HDR.equals(status)) {
			setSRCH_HDRStatus();
		}
		else if (SRCH_DTL.equals(status)) {
			setSRCH_DTLStatus();
		}
		else if (DEL_HDR.equals(status)) {
			setDEL_HDRStatus();
		}
		else if (DEL_DTL.equals(status)) {
			setDEL_DTLStatus();
		}
		else if (REF_HDR.equals(status)) {
			setREF_HDRStatus();
		}
		else if (REF_DTL.equals(status)) {
			setREF_DTLStatus();
		}
		else if (PRNT_HDR.equals(status)) {
			setPRNT_HDRStatus();
		}
		else if (SEND_HDR.equals(status)) {
			setSEND_HDRStatus();
		}
	}

